CREATE TABLE files (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,owner_id TEXT NOT NULL,bucket TEXT NOT NULL,object_key TEXT NOT NULL,filename TEXT NOT NULL,content_type TEXT NOT NULL,size BIGINT NOT NULL CHECK(size>0),checksum_sha256 TEXT NOT NULL,status TEXT NOT NULL,scan_status TEXT NOT NULL,idempotency_key TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE(bucket,object_key),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX files_tenant_owner_idx ON files(tenant_id,owner_id,created_at DESC); CREATE INDEX files_lifecycle_idx ON files(status,updated_at);
